class Solution { fun canPartitionKSubsets(nums:IntArray,k:Int):Boolean{val sum=nums.sum();if(sum%k!=0)return false;val target=sum/k;nums.sort();if(nums.last()>target)return false;val buckets=IntArray(k);fun place(index:Int):Boolean{if(index<0)return true;val value=nums[index];var previous=-1;for(bucket in buckets.indices){if(buckets[bucket]==previous||buckets[bucket]+value>target)continue;previous=buckets[bucket];buckets[bucket]+=value;if(place(index-1))return true;buckets[bucket]-=value;if(buckets[bucket]==0)break};return false};return place(nums.lastIndex)} }
